{"results": [{"id": "FAM:SF-APPS-088", "label": "Study family SF-APPS-088: Offensive-identity resilience: connector absence vs usage-matched others", "score": 1.434, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-088 (0.82)", "request matches RQC:RQC-013 (0.82); FAM:SF-APPS-088 auto_addresses_question RQC:RQC-013"], "attributes": {"observed_research_question": "Offensive-identity resilience: connector absence vs usage-matched others", "auto_outcome_status": "supported", "observed_hypothesis": "Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence.", "observed_result": "Unmatched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08. Usage-matched vs role: paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96. Vs terminal: +0.0777 t=2.37 p=0.0261 n=25.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Usage-matched connector vs role occupant identity break is large and significant (n=96). Licensed comparison excludes organizers.", "observed_sample_and_power": "n=96 matched pairs vs role; n=25 vs terminal; 908 player-seasons"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-014"}]}, {"id": "FAM:SF-PAP-014", "label": "Study family SF-PAP-014: On/off identity displacement D_A (shaper vs usage-matched role occupant)", "score": 1.434, "reached_via": ["FAM:SF-APPS-088 auto_related_family (repeated_by_later_family) FAM:SF-PAP-014", "FAM:SF-APPS-088 auto_related_family (repeat_of_earlier_family) FAM:SF-PAP-014"], "attributes": {"observed_research_question": "On/off identity displacement D_A (shaper vs usage-matched role occupant)", "auto_outcome_status": "supported", "observed_hypothesis": "Real on/off absence of a shaper displaces the team fing